from lib89 import *
def B(ch,tn,*a,**k): build('english',ch,tn,*a,**k)
B(5,'The World of Limitless Possibilities','The World of Limitless Possibilities: an interview with Dr. Deepa Malik','Ability beyond disability',
 "What would you do if doctors said you would never walk again? Dr. Deepa Malik chose to turn that moment into a world of limitless possibilities. Her interview shows how courage changes lives.",
 [("The interviewer introduces Dr. Deepa Malik, listed by the International Paralympic Committee among the ten most inspirational women para-athletes in the world.","who she is"),
  ("At 29 she was diagnosed with a spinal tumour. After surgery she was paralysed from the waist down and told she would be bound to a wheelchair.","the tragedy"),
  ("She said she had two choices: waste her life in regret or transform it into a world of limitless possibilities.","two choices"),
  ("Loving sports and having been a swimmer, she switched to para-athletics. Her breakthrough was the silver medal in shot-put at the 2016 Rio Paralympic Games.","breakthrough"),
  ("She is the first Indian woman para-athlete to win an Asian Games athletics medal and India's first female Paralympic medallist in any sport.","firsts"),
  ("She believes physical limitations do not define potential and supports the idea of ability beyond disability. Her main challenge was society underestimating her abilities, overcome with mental resilience and family support.","her philosophy"),
  ("She says sports challenge stereotypes because people who see para-athletes' strength and skill drop their preconceived notions.","sports and stereotypes"),
  ("She works for inclusivity: emotional health of persons with challenges, women's outdoor adventure, equipment for para sportspersons, and awareness sessions in schools. Her advice is that every setback is an opportunity and disability is a unique strength to be unleashed.","advocacy and advice")],
 ("Separate fact from opinion: 'I secured the silver medal in Rio in 2016' and 'It was a moment of personal victory'.",[("The first sentence can be checked in records.","Fact."),("The second is her own feeling.","Opinion."),("Facts are provable; opinions express beliefs.","Rule.")]),
 ("What does 'ability beyond disability' mean?",["Skill matters more than limitation","Resilience and support","Challenging stereotypes"],["Thinking disability means no potential"]),
 ["Dr. Malik turned a tragedy into achievement.","Facts can be proved; opinions are beliefs.","Sport can break stereotypes.","Setbacks are opportunities to prove strength."],
 [mcq("e5-1",1,"At what age was Dr. Malik diagnosed with a spinal tumour?","29",["19","39"],"She was 29."),
  mcq("e5-2",1,"Which medal did she win at Rio 2016 in shot-put?","Silver",["Gold","Bronze"],"A silver medal."),
  tf("e5-3",1,"She chose to waste her life in remorse.",False,"She chose to transform it."),
  mcq("e5-4",2,"What was a major challenge she faced?","Societal perceptions underestimating her",["Lack of interest","No wheelchair"],"People underestimated her."),
  mcq("e5-5",2,"'Ability beyond disability' means","skill matters beyond physical limits",["disability is a weakness","sport is not for all"],"Her philosophy."),
  tf("e5-6",2,"She supports awareness sessions in schools and colleges.",True,"She organises them."),
  short("e5-7",3,"Which Games gave her the silver medal in 2016? (city)",["rio","rio de janeiro"],"The Rio Paralympic Games."),
  mcq("e5-8",3,"'I secured a silver medal' is a","fact",["opinion","cause"],"It can be verified.")])
B(6,'Twin Melodies','Twin Melodies (play by Mitra Phukan)','Classical, fusion and family',
 "Can a young violinist play Indo-Western fusion and still respect her father's classical tradition? This play shows how a family finds harmony.",
 [("The characters are Shruti Sharma, a young violinist; her father Guru Nabin Sharma, a violinist and principal of the Sangeetika Music School; her mother Leela Devi; and her band friends Avinash (tabla), Iqbal (flute) and Peter (keyboard).","characters"),
  ("Act I is set in Iqbal's room after a fusion rehearsal. A newspaper has praised Shruti's performance with her father, but she looks distressed because she has not told her father about the fusion concert.","Act I"),
  ("Shruti explains that her father is strict and believes only classical Hindustani music with ragas and alaaps is worthy. She does not want to disrespect his opinion but wants to try fusion too.","Shruti's worry"),
  ("Her friends encourage her to speak up, and she promises to tell him at dinner.","friends encourage"),
  ("In Act II, over dinner, Shruti tells her father about an Indo-Western fusion concert. He refuses calmly but firmly, saying one performance every six months is his rule and that fusion makes the violinist lose musicality.","Act II"),
  ("Later Shruti's parents come to her rehearsal. Her mother Leela reminds Nabin of his own past: his family were classical vocalists and his father saw his choice of a Western instrument, the violin, as a betrayal of family tradition.","Leela's reminder"),
  ("Nabin admits he had forgotten his past and that he underestimated the power of Indian music. He promises to support Shruti's group at the concert.","Nabin changes"),
  ("The play shows that tradition and change can live together, and that listening and courage can bring families closer. Twin melodies means two kinds of music in harmony.","theme")],
 ("Why does Shruti hesitate to tell her father about the concert?",[("Her father believes only classical music is worthwhile.","His strict view."),("She does not want to hurt or disrespect him.","Her love."),("Hence she delays telling him.","Answer.")]),
 ("How does the play show that tradition and change can coexist?",["Nabin's own past","Shruti respects her art","Both genres have value"],["Thinking all fusion music disrespects tradition"]),
 ["Shruti plays fusion and respects classical music.","Nabin first refuses, then understands.","Leela reminds him of his own past.","The play teaches openness between generations."],
 [mcq("e6-1",1,"Who wrote Twin Melodies?","Mitra Phukan",["Sudha Murty","Temsula Ao"],"Mitra Phukan."),
  mcq("e6-2",1,"Shruti plays the","violin",["tabla","flute"],"She is a violinist."),
  tf("e6-3",1,"Nabin Sharma strongly supported fusion at the start.",False,"He refused."),
  mcq("e6-4",2,"Which friend plays the tabla?","Avinash",["Iqbal","Peter"],"Avinash plays tabla."),
  mcq("e6-5",2,"Who reminded Nabin of his past?","Leela",["Iqbal","Peter"],"Shruti's mother."),
  tf("e6-6",2,"Nabin's own father disapproved of his choice of the violin.",True,"A family of vocalists."),
  short("e6-7",3,"Which type of music did Nabin believe was the only worthy kind? (two words)",["classical hindustani","hindustani classical","classical music"],"Classical Hindustani music."),
  mcq("e6-8",3,"At the end Nabin","promises to support the concert",["stops her music","leaves home"],"He roots for her group.")])
B(7,'Carrier of Words','Carrier of Words: the Gramin Dak Sewak of the Thar','The postman who walks the sand',
 "In a time of instant messages, a letter can still take a long walk through the desert. This feature about the postman Khetaram shows what it takes to carry words to faraway homes.",
 [("The piece opens with how a letter travels through the postal system to a postman and finally to a letter box.","the letter's journey"),
  ("In areas beyond the last railhead and where the road ends in soft sand, Gramin Dak Sewaks (GDS) are the only link between remote communities and their families.","GDS as a link"),
  ("Khetaram has been the sole postman of Somarad Branch Post Office in Rajasthan for fifteen years, in the Thar desert only 2.5 km short of the Indo-Pakistan border.","Khetaram"),
  ("His left shoulder is slumped from carrying a mailbag. The regulation limit is 28 kg and the mail must reach the border within 24 hours of dispatch from Jodhpur.","the load"),
  ("He walks on hot sand where temperatures cross 50 degrees. Sometimes he delivers after sundown, and water is too precious to wash with, so he can only wipe his body.","desert hardship"),
  ("Until 2001 he was known as a delivery agent. India has over three lakh GDS, who form more than half the postal workforce, serving places from Ladakh to Lakshadweep and the northeast.","India Post and GDS"),
  ("After independence India Post aimed to bring everyone within the mailing range, growing from about 25,000 post offices in 1947 to over a lakh and a half today. Rural depositors trust the post office with their savings.","India Post's mission"),
  ("GDS selection needs another means of livelihood and only five working hours a day, which helps keep workers in remote outposts. For Khetaram, in a land of famine and one crop of bajra, the job gave a new lease of life.","conditions and meaning")],
 ("Why is the work of a GDS called invaluable?",[("They deliver where roads, trains and phones do not reach.","Last mile."),("They carry mail and savings to remote people.","Trust."),("So they link villages with the nation.","Importance.")]),
 ("What qualities does Khetaram's job need?",["Physical endurance","Dedication","Trust of the people"],["Thinking a postman's work is easy"]),
 ["GDS reach the remotest places.","Khetaram walks the Thar to deliver mail.","India Post serves the whole population.","Dedication links communities."],
 [mcq("e7-1",1,"Khetaram works in which desert?","Thar",["Sahara","Gobi"],"The Thar."),
  mcq("e7-2",1,"GDS stands for","Gramin Dak Sewak",["Great Delivery System","Government Dak Service"],"Gramin Dak Sewak."),
  tf("e7-3",1,"Khetaram has been postman for fifteen years.",True,"As stated."),
  mcq("e7-4",2,"The regulation limit for his mailbag is","28 kg",["50 kg","10 kg"],"28 kilos."),
  mcq("e7-5",2,"Why does water matter so much to him?","It is too precious to waste on washing",["He sells it","There is a lot of it"],"He only wipes his body."),
  tf("e7-6",2,"GDS form more than half of the postal workforce.",True,"Over three lakh of them."),
  short("e7-7",3,"Which town is the last railhead near Somarad? (one word)",["barmer"],"Barmer."),
  mcq("e7-8",3,"The piece mainly shows","the dedication of a rural postman",["a tourist trip","a cricket match"],"A tribute to GDS.")])
B(8,'Follow That Dream','Follow That Dream: a mother\'s letter about dreams','Count the cost, then plunge',
 "Everyone has a dream. This warm letter from a mother to her children explains what it takes to chase one, and what to do when life changes it.",
 [("The text is a letter signed 'Love, Mum', in which the writer shares her thoughts on following dreams.","a letter"),
  ("She says it starts with passion for an interest, then comes the conviction that it must be realised.","passion first"),
  ("Next you must count the cost in years of effort, money and sacrifice. If it still burns in your blood, you plunge into the task, in any field: sports, science, arts, business or design.","count the cost"),
  ("The road is uphill, and often you are kept afloat only by knowing you are doing what you love and doing the right thing.","uphill road"),
  ("She points out that award winners thank many people, showing that for one winner there is a group who stood by them, a support network.","support network"),
  ("Many dreams remain dreams. Some people never get beyond wishful thinking, some trade the dream for security, and some are changed by circumstances, such as a war or the need to support siblings.","why dreams fail"),
  ("She does not put a wet blanket on your dreams, but asks you to consider the years you need to chase them and to go ahead if the conviction is still burning.","think and go ahead"),
  ("Life may change a person's dream, and the new hopes are no less than the original. Her own dream changed over ten years into publishing this book, and she wishes at least one of the children's dreams comes true.","dreams change")],
 ("List the steps the writer gives for chasing a dream.",[("Passion for an interest and the conviction to realise it.","Start."),("Count the cost: years, money, sacrifice.","Think."),("If still burning, commit to the task.","Act.")]),
 ("What advice does the letter give about dreams?",["Count the cost","Build a support network","Be ready for dreams to change"],["Thinking dreams need no sacrifice"]),
 ["A dream starts with passion and conviction.","Count the cost, then commit.","A support network helps.","Dreams may change and still be worthwhile."],
 [mcq("e8-1",1,"The text is","a letter from a mother",["a news report","a play"],"It ends with Love, Mum."),
  mcq("e8-2",1,"The writer says you should first count the cost in","years, money and sacrifice",["marks","friends only"],"Effort, finances and sacrifice."),
  tf("e8-3",1,"The writer says the road to a dream is always easy.",False,"It is uphill."),
  mcq("e8-4",2,"Why do many dreams remain dreams?","People never move beyond wishful thinking",["Dreams are illegal","Dreams are free"],"They do not act."),
  mcq("e8-5",2,"Award winners thank many people to show","the value of a support network",["they are shy","luck"],"A group stands behind a winner."),
  tf("e8-6",2,"The writer believes dreams may change over time.",True,"Her own dream changed."),
  short("e8-7",3,"What does the writer say she did over ten years? (one word: book)",["book","publish","publishing a book"],"She chased the dream of publishing a book."),
  mcq("e8-8",3,"'Wishful thinking' means","wishing without acting",["working hard","giving up"],"Not going beyond wishes.")])
